INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1535692-econ401', 'stk-doi', 'ECON 401', 'info', '{"desc": "Mehmet Soytas\nEcon-401 - Term 221:\n\nالتحضير: بداية الكلاس ورقه ويوقعون عليها الطلاب ويخذها اخر الكلاس، ما يقول شي عن التأخير.\n\nطريقة الشرح: اعظم دكتور بالجامعه شرح، سلايدات ويبسطها لك برسمات ونفسه حلوه ودايماً مبتسم .\n\nالـQuizes: ما فيه كوزات\n\nالـMidterm: ميجرين كل واحد عليه ٣٠٪؜ ويعطيك ١٠٠ سوال قبل الميجر تقريباً نفس الي بتجيك بالميجر\n\nالـFinal: الفاينل من ٣٥٪؜ نفس طريقة المياجر على كلامه ولسى ادرس عنده ما خلصنا الفاينل\n\nالقريد النهائي: فوق التقيم\n\nإضافات: الدكتور جبار بس لازم تركز معه بالكلاس، الصوت واضح جدا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mehmet-soytas-or-mustafa-ba-biker/183487/4", "user": "DOI", "ts": 1666896569000, "tid": 183487, "pn": 4}}', 1666896569000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
